() => {
  const r = {};
  r.fonts = document.fonts.check('800 72px Inter');
  const root = document.getElementById('root');
  r.rootBox = root.getBoundingClientRect().toJSON();
  r.scrollH = root.scrollHeight;
  r.clientH = root.clientHeight;
  const img = document.querySelector('.photo img');
  r.photoNat = [img.naturalWidth, img.naturalHeight];
  const sel = ['.headline','.photo','.cands','.cta','.steps','.footer'];
  r.sections = sel.map(s=>{const b=document.querySelector(s).getBoundingClientRect();return [s, Math.round(b.x), Math.round(b.y), Math.round(b.width), Math.round(b.height)];});
  // overflow check
  r.overflow = [...document.querySelectorAll('#root *')].filter(e=>e.scrollWidth>e.clientWidth+1).map(e=>e.className+':'+e.scrollWidth+'/'+e.clientWidth);
  return r;
}

