  const sel=['.headline','.photo','.cands','.cta','.steps','.footer'];
  r.s=sel.map(s=>{const b=document.querySelector(s).getBoundingClientRect();return [s,+b.y.toFixed(1),+b.height.toFixed(1),+b.width.toFixed(1)];});
  const root=document.getElementById('root');
  r.root=[root.getBoundingClientRect().width,root.getBoundingClientRect().height];
  r.overflowY = root.scrollHeight - root.clientHeight;
  r.lineClip=[...document.querySelectorAll('.cta span,.cand .nm,.step span,.footer')].map(e=>[e.textContent.slice(0,14),e.scrollWidth-e.clientWidth]);
  return r;
}

