async () => {
  const out = {};
  for (const f of ['portrait.png','wide.png','sky.png']) {
    const r = await fetch('/' + f + '?t=' + Date.now());
    const blob = await r.blob();
    const bmp = await createImageBitmap(blob);
    out[f] = { w: bmp.width, h: bmp.height, kb: Math.round(blob.size/1024) };
  }
  return out;
}

